// Lift the kick-off block on para_cp0150 (team 1), then bring out
// their Fighting Spirit ck0013
CMND_BTL_SET_MATCH_PHASE(0, 300);
CMND_BTL_SET_DISABLE_AVATER("para_cp0150", false);
CMND_BTL_SET_AVATER("para_cp0150", "ck0013", 1);

// Dismiss the team's Fighting Spirits if three or more are out,
// then bring out para_cp0016's Fighting Spirit ck0005 (team 0)
if (CMND_BTL_GET_AVATER_NUM(0) >= 3)
{
	CMND_BTL_RESET_AVATER(0);
}

CMND_BTL_SET_AVATER("para_cp0016", "ck0005", 0);
